## 9. Hands-On: Building a Complete Example

### Module Structure

```
app/code/Vendor/Module/
  view/
    frontend/
      web/
        js/
          greeting-widget.js
      templates/
        greeting.phtml
  i18n/
    en_US.csv
    fr_FR.csv
```

### Step 1: Define the Widget

```javascript
// app/code/Vendor/Module/view/frontend/web/js/greeting-widget.js

define([
    "jquery",
    "mage/translate"
], function ($, $t) {
    "use strict";

    $.widget("vendor.greetingWidget", {

        // Default options
        options: {
            name: "World",
            showCount: true,
            count: 0
        },

        /**
         * Widget constructor - runs ONCE
         */
        _create: function () {
            console.log("greetingWidget created");

            // One-time DOM setup
            this._buildUI();

            // Bind events ONCE in _create
            this._on(this.element, {
                "click .greeting-button": "_onButtonClick"
            });
        },

        /**
         * Initialization - runs on create AND re-init
         */
        _init: function () {
            console.log("greetingWidget initialized");
            this._updateGreeting();
        },

        /**
         * Build the UI structure once
         * @private
         */
        _buildUI: function () {
            // Create elements
            this.$greeting = $("<p>", { "class": "greeting-text" });
            this.$button = $("<button>", {
                "class": "greeting-button action primary",
                "type": "button",
                "text": $t("Say Hello")   // <-- JS translation
            });
            this.$counter = $("<span>", { "class": "greeting-counter" });

            // Append to widget element
            this.element
                .append(this.$greeting)
                .append(this.$button)
                .append(this.$counter);
        },

        /**
         * Update the greeting message
         * @private
         */
        _updateGreeting: function () {
            // JS translation with dynamic value
            var greeting = $t("Hello, %1!").replace(
                "%1",
                this.options.name
            );

            this.$greeting.text(greeting);

            if (this.options.showCount) {
                var countText = $t("Clicked %1 times").replace(
                    "%1",
                    this.options.count
                );
                this.$counter.text(countText);
            }
        },

        /**
         * Button click handler
         * @private
         */
        _onButtonClick: function (event) {
            event.preventDefault();
            this.incrementCount();
        },

        /**
         * Public method to increment the counter
         */
        incrementCount: function () {
            this.options.count++;
            this._updateGreeting();

            // Trigger custom event
            this._trigger("countIncremented", null, {
                count: this.options.count
            });
        },

        /**
         * Handle option changes
         */
        _setOption: function (key, value) {
            this._super(key, value); // Always call _super!
            this._updateGreeting();
        },

        /**
         * Cleanup when widget is destroyed
         */
        _destroy: function () {
            this.element.empty(); // Remove DOM we added
        }
    });

    return $.vendor.greetingWidget;
});
```

### Step 2: Template with `data-mage-init`

```html
<!-- app/code/Vendor/Module/view/frontend/templates/greeting.phtml -->

<div class="greeting-wrapper"
     data-mage-init='{"Vendor_Module/js/greeting-widget": {
         "name": "<?= $block->escapeJs($block->getName()) ?>",
         "showCount": true,
         "count": 0
     }}'>
</div>
```

### Step 3: Template with `x-magento-init`

