<script type="text/x-magento-init">
{
    "#greeting-component": {
        "Vendor_Module/js/greeting-widget": {
            "name": "<?= $block->escapeJs($block->getName()) ?>",
            "showCount": true,
            "count": 0
        }
    }
}
</script>
```

