## 8. Hands-On: AMD Module with AJAX

### Objective

Build a complete AMD module that:
1. Fetches customer cart data via REST API
2. Uses `mage/storage` for the AJAX call
3. Handles success and error states
4. Is properly translated
5. Can be verified in the browser network tab

### Step 1: Create the Module File

```bash
mkdir -p app/code/Vendor/Training/view/frontend/web/js
touch app/code/Vendor/Training/view/frontend/web/js/cart-info.js
```

```javascript
// app/code/Vendor/Training/view/frontend/web/js/cart-info.js

define([
    'jquery',
    'mage/storage',
    'mage/url',
    'mage/translate',
    'Magento_Customer/js/model/customer',
    'Magento_Checkout/js/model/quote'
], function ($, storage, urlBuilder, $t, customer, quote) {
    'use strict';

    /**
     * Cart Info Module
     * Demonstrates AMD structure with mage/storage AJAX calls
     */
    return {

        /**
         * Module entry point
         */
        init: function () {
            console.log($t('Cart Info module initialized'));
            this.loadCartItems();
        },

        /**
         * Fetch cart items via REST API
         * @returns {jQuery.Deferred}
         */
        loadCartItems: function () {
            var self = this,
                serviceUrl;

            // Build the correct URL based on login state
            if (customer.isLoggedIn()) {
                serviceUrl = urlBuilder.build('rest/V1/carts/mine/items');
            } else {
                // For guests, we need the masked cart ID
                // Guest cart uses the masked quote ID from checkoutConfig, NOT form_key
                var guestCartId = window.checkoutConfig.quoteData.entity_id;
                serviceUrl = urlBuilder.build('rest/V1/guest-carts/' + guestCartId + '/items');
            }

            console.log($t('Fetching cart from: %1').replace('%1', serviceUrl));

            // Make the AJAX call — mage/storage handles auth headers automatically
            return storage.get(serviceUrl, false)
                .done(function (response) {
                    self._onSuccess(response);
                })
                .fail(function (xhr) {
                    self._onError(xhr);
                })
                .always(function () {
                    console.log($t('Cart request completed'));
                });
        },

        /**
         * POST example: Add item to cart
         * @param {String} sku
         * @param {Number} qty
         * @returns {jQuery.Deferred}
         */
        addToCart: function (sku, qty) {
            var serviceUrl = urlBuilder.build('rest/V1/carts/mine/items');

            var payload = JSON.stringify({
                cartItem: {
                    sku: sku,
                    qty: qty,
                    quote_id: quote.getQuoteId()
                }
            });

            return storage.post(serviceUrl, payload)
                .done(function (response) {
                    console.log($t('Item added to cart:'), response);
                })
                .fail(function (xhr) {
                    console.error($t('Failed to add item'), xhr.responseJSON);
                });
        },

        /**
         * Success handler
         * @param {Array} items
         * @private
         */
        _onSuccess: function (items) {
            console.log(
                $t('Cart contains %1 item(s)').replace('%1', items.length),
                items
            );
        },

        /**
         * Error handler
         * @param {Object} xhr
         * @private
         */
        _onError: function (xhr) {
            var errorMsg = (xhr.responseJSON && xhr.responseJSON.message)
                ? xhr.responseJSON.message
                : $t('An unknown error occurred');

            console.error($t('Cart load failed: %1').replace('%1', errorMsg));
        }
    };
});
```

### Step 2: Register Module Alias

```javascript
// app/code/Vendor/Training/view/frontend/requirejs-config.js

var config = {
    // Note: a self-referencing map entry like 'Vendor_Training/js/cart-info': 'Vendor_Training/js/cart-info'
    // is unnecessary — RequireJS resolves module paths automatically.
    // Only add map entries when creating SHORT aliases for long paths:
    map: {
        '*': {
            'cartInfo': 'Vendor_Training/js/cart-info'
        }
    }
};
```

### Step 3: Create a Layout XML to Load the Module

```xml
<!-- app/code/Vendor/Training/view/frontend/layout/default.xml -->
<?xml version="1.0"?>
<page xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
      xsi:noNamespaceSchemaLocation="urn:magento:framework:View/Layout/etc/page_configuration.xsd">
    <body>
        <referenceContainer name="before.body.end">
            <block class="Magento\Framework\View\Element\Template"
                   name="vendor.training.cart.info"
                   template="Vendor_Training::cart-info.phtml" />
        </referenceContainer>
    </body>
</page>
```

### Step 4: Create the Template (PHTML)

```php
<?php
// app/code/Vendor/Training/view/frontend/templates/cart-info.phtml
?>
<script>
require(['Vendor_Training/js/cart-info'], function (cartInfo) {
    'use strict';

    // Initialize module when DOM is ready
    cartInfo.init();
});
</script>
```

### Step 5: Alternatively — Use `data-mage-init`

For component-style initialization via `data-mage-init`:

```html
<!-- In a .phtml template -->
<div data-mage-init='{"Vendor_Training/js/cart-info": {}}'></div>
```

> **How `data-mage-init` dispatches:** When the module loads, `mage/apply/main.js` checks the export type:
> 1. If the module returns a **function** → calls `fn(config, element)` (most common for non-widget components)
> 2. If the module returns an **object** → looks for `obj[componentPath]` property and calls it
> 3. If neither → checks if `$(element)[componentName]` exists (jQuery widget) and calls `$(el).widgetName(config)`
>
> It does **NOT** automatically call an `init()` method. For a plain object module like `cart-info.js`, you would need to return a function instead, or use the `require()` + manual init approach from Step 4.

